import { Component, signal, effect } from '@angular/core';

// ❌ OLD: The manual pattern — a loading/data/error signal trio updated
// from an effect. Verbose, and prone to races (a slow first request
// can overwrite a fast second one).
@Component({
  selector: 'app-user',
  template: `{{ loading() ? 'Loading…' : data()?.name }}`,
})
export class UserComponent {
  userId = signal(1);
  data = signal<User | null>(null); // ❌ OLD
  loading = signal(false); // ❌ OLD
  error = signal<Error | null>(null); // ❌ OLD

  constructor() {
    effect(async () => {
      const id = this.userId();
      this.loading.set(true);
      try {
        this.data.set(await fetch(`/users/${id}`).then((r) => r.json()));
      } catch (e) {
        this.error.set(e as Error); // ❌ OLD: race — stale response can win
      } finally {
        this.loading.set(false);
      }
    });
  }
}

