import { Component, signal, resource } from '@angular/core';

// ✅ NEW: resource() manages the whole lifecycle — request tracking,
// loading/error/value state, and race protection (stale responses are
// discarded). No effect, no signal trio.
@Component({
  selector: 'app-user',
  template: `
    @if (user.isLoading()) { <p>Loading…</p> }
    @else { <p>{{ user.value()?.name }}</p> }
  `,
})
export class UserComponent {
  userId = signal(1);

  // ✅ NEW: request is a computation; loader re-runs when it changes
  user = resource({
    request: () => this.userId(),
    loader: ({ request }) => fetch(`/users/${request}`).then((r) => r.json()),
  });

  // Access: user.value(), user.isLoading(), user.error(), user.status()
}

